import hashlib,importlib.metadata,json,platform
from datetime import datetime,timezone
from pathlib import Path
import duckdb,networkx as nx,pyarrow as pa,pyarrow.parquet as pq
P=Path(__file__).resolve().parent;OUT=P/'output';ROOT=P.parents[1]
L1={'Pattern_L1_A':{'nodes':[('a','A'),('b','B')],'edges':[('a','b','R1')]},'Pattern_L1_B':{'nodes':[('c','C'),('d','D')],'edges':[('c','d','R2')]}}
def originals():
 gs=[]
 for i in range(12):
  g=nx.DiGraph(graph_id=f'g{i:02d}')
  if i<10:
   for role,kind in L1['Pattern_L1_A']['nodes']:g.add_node(f'{role}{i}',kind=kind)
   for role,kind in L1['Pattern_L1_B']['nodes']:g.add_node(f'{role}{i}',kind=kind)
   g.add_edge(f'a{i}',f'b{i}',relation='R1');g.add_edge(f'c{i}',f'd{i}',relation='R2');g.add_edge(f'b{i}',f'c{i}',relation='Bridge')
  else:
   for j in range(4):g.add_node(f'r{i}_{j}',kind=f'Random_{i}_{j}')
   g.add_edge(f'r{i}_0',f'r{i}_2',relation=f'noise_{i}_0');g.add_edge(f'r{i}_3',f'r{i}_1',relation=f'noise_{i}_1');g.add_edge(f'r{i}_0',f'r{i}_3',relation=f'noise_{i}_2')
  gs.append(g)
 return gs
def reconstruct(occ):
 g=nx.DiGraph();bind=occ['original_bindings']
 for pid in ('Pattern_L1_A','Pattern_L1_B'):
  for role,kind in L1[pid]['nodes']:g.add_node(bind[role],kind=kind)
  for x,y,r in L1[pid]['edges']:g.add_edge(bind[x],bind[y],relation=r)
 g.add_edge(bind['b'],bind['c'],relation='Bridge');return g
def integrated_hierarchy():
 paths={poc:ROOT/f'poc/{poc}/output/results.json' for poc in ('ind-01','ind-02','ind-03')};raw={poc:path.read_bytes() for poc,path in paths.items()};sources={poc:json.loads(content) for poc,content in raw.items()};fca=sources['ind-01']['integrated_hypothesis_context'];ilp=sources['ind-02']['integrated_fca_ilp'];subgraph=sources['ind-03']['integrated_justification_pattern']
 concept_id=ilp['target']['anonymous_concept_id'];concept=next(row for row in fca['concepts'] if row['id']==concept_id);concept_members=set(concept['extent']);graph_members={row['hypothesis_id'] for row in subgraph['occurrences']};level2_members=sorted(concept_members&graph_members)
 graph_pattern_id=subgraph['pattern']['id'];concept_pattern_id=f'Pattern_FCA_{concept_id}';level2_id='Pattern_L2_FCA_Justification_001'
 graph_occurrence={row['hypothesis_id']:f"{graph_pattern_id}:{row['hypothesis_id']}" for row in subgraph['occurrences']};concept_occurrence={hypothesis_id:f'{concept_pattern_id}:{hypothesis_id}' for hypothesis_id in concept_members}
 level2_occurrences=[{'occurrence_id':f'{level2_id}:{hypothesis_id}','pattern_id':level2_id,'hypothesis_id':hypothesis_id,'child_occurrence_ids':[concept_occurrence[hypothesis_id],graph_occurrence[hypothesis_id]],'hypothesis_artifact_id':next(row['hypothesis_artifact_id'] for row in fca['objects'] if row['hypothesis_id']==hypothesis_id)} for hypothesis_id in level2_members]
 hierarchy_rows=[{'pattern_id':concept_pattern_id,'level':1,'dependencies_json':'[]'},{'pattern_id':graph_pattern_id,'level':1,'dependencies_json':'[]'},{'pattern_id':level2_id,'level':2,'dependencies_json':json.dumps([concept_pattern_id,graph_pattern_id],sort_keys=True)}];write_occ=[{**row,'child_occurrence_ids_json':json.dumps(row.pop('child_occurrence_ids'))} for row in json.loads(json.dumps(level2_occurrences))]
 pq.write_table(pa.Table.from_pylist(hierarchy_rows),OUT/'integrated-pattern-hierarchy.parquet',compression='zstd');pq.write_table(pa.Table.from_pylist(write_occ),OUT/'integrated-level2-occurrences.parquet',compression='zstd')
 graph_cost=len(subgraph['pattern']['canonical_form']['nodes'])+len(subgraph['pattern']['canonical_form']['edges']);concept_cost=max(1,len(ilp['learned_body_attributes']));raw_units=len(graph_members)*graph_cost+len(concept_members)*concept_cost;level1_units=graph_cost+concept_cost+len(graph_members)+len(concept_members);level2_dictionary=3;residual_graph_refs=len(graph_members-concept_members);level2_units=graph_cost+concept_cost+level2_dictionary+len(level2_occurrences)+residual_graph_refs
 details={'sources':{f'{poc}_results_sha256':hashlib.sha256(content).hexdigest() for poc,content in raw.items()},'patterns':hierarchy_rows,'level2_occurrences':level2_occurrences,'negative_witness_hypothesis_ids':sorted(graph_members-concept_members),'description_length':{'unit':'one structural item or occurrence reference','raw_units':raw_units,'after_level1_units':level1_units,'after_level2_units':level2_units,'level1_gain':raw_units-level1_units,'recursive_additional_gain':level1_units-level2_units},'decision':{'action':'retain_hierarchical_candidate','promote':False,'reason':'hierarchy is exact but two occurrences do not amortize its level-2 dictionary cost'}}
 validations={'actual_upstream_pocs_valid':all(all(source['validations'].values()) for source in sources.values()),'actual_ilp_membership_matches_fca_extent':set(ilp['covered_hypothesis_ids'])==concept_members,'actual_level2_is_intersection':{row['hypothesis_id'] for row in level2_occurrences}==concept_members&graph_members=={'hyp:H1','hyp:H3'},'actual_each_occurrence_links_two_level1_occurrences':all(len(row['child_occurrence_ids'])==2 for row in level2_occurrences),'actual_artifact_ids_preserved':all(row['hypothesis_artifact_id'].startswith('ca:hypothesis-version:') for row in level2_occurrences),'actual_negative_witnesses_retained':details['negative_witness_hypothesis_ids']==['hyp:H2','hyp:H4'],'actual_level1_compression_positive':raw_units>level1_units,'actual_recursive_gain_honestly_negative':level2_units>level1_units and details['decision']['promote'] is False}
 return details,validations
def main():
 OUT.mkdir(parents=True,exist_ok=True);gs=originals();l1_occ=[];l2_occ=[]
 for i,g in enumerate(gs[:10]):
  gid=g.graph['graph_id'];oa={'occurrence_id':f'{gid}:l1a','pattern_id':'Pattern_L1_A','graph_id':gid,'bindings_json':json.dumps({'a':f'a{i}','b':f'b{i}'},sort_keys=True)};ob={'occurrence_id':f'{gid}:l1b','pattern_id':'Pattern_L1_B','graph_id':gid,'bindings_json':json.dumps({'c':f'c{i}','d':f'd{i}'},sort_keys=True)};l1_occ += [oa,ob];l2_occ.append({'occurrence_id':f'{gid}:l2','pattern_id':'Pattern_L2_AB','graph_id':gid,'child_occurrence_ids_json':json.dumps([oa['occurrence_id'],ob['occurrence_id']]),'original_bindings_json':json.dumps({'a':f'a{i}','b':f'b{i}','c':f'c{i}','d':f'd{i}'},sort_keys=True)})
 patterns=[{'pattern_id':'Pattern_L1_A','level':1,'dependencies_json':'[]','canonical_json':json.dumps(L1['Pattern_L1_A'],sort_keys=True)},{'pattern_id':'Pattern_L1_B','level':1,'dependencies_json':'[]','canonical_json':json.dumps(L1['Pattern_L1_B'],sort_keys=True)},{'pattern_id':'Pattern_L2_AB','level':2,'dependencies_json':json.dumps(['Pattern_L1_A','Pattern_L1_B']),'canonical_json':json.dumps({'nodes':[('p1','Pattern_L1_A'),('p2','Pattern_L1_B')],'edges':[('p1','p2','Bridge')]},sort_keys=True)}]
 pq.write_table(pa.Table.from_pylist(patterns),OUT/'patterns.parquet',compression='zstd');pq.write_table(pa.Table.from_pylist(l1_occ),OUT/'level1-occurrences.parquet',compression='zstd');pq.write_table(pa.Table.from_pylist(l2_occ),OUT/'level2-occurrences.parquet',compression='zstd')
 con=duckdb.connect();paths={n:str((OUT/f'{n}.parquet').resolve()).replace("'","''") for n in ('patterns','level1-occurrences','level2-occurrences')};con.execute(f"CREATE VIEW patterns AS SELECT * FROM read_parquet('{paths['patterns']}')");con.execute(f"CREATE VIEW l1 AS SELECT * FROM read_parquet('{paths['level1-occurrences']}')");con.execute(f"CREATE VIEW l2 AS SELECT * FROM read_parquet('{paths['level2-occurrences']}')");counts={'patterns_by_level':{str(level):count for level,count in con.execute('SELECT level,count(*) FROM patterns GROUP BY level ORDER BY level').fetchall()},'l1_occurrences':con.execute('SELECT count(*) FROM l1').fetchone()[0],'l2_occurrences':con.execute('SELECT count(*) FROM l2').fetchone()[0],'original_graph_support':con.execute('SELECT count(DISTINCT graph_id) FROM l2').fetchone()[0]};con.close()
 # Description units: one per node/edge; one per occurrence reference; residual links and witnesses remain explicit.
 raw=sum(g.number_of_nodes()+g.number_of_edges() for g in gs);l1_dictionary=6;l1_references=len(l1_occ);bridges=len(l2_occ);random_residual=sum(g.number_of_nodes()+g.number_of_edges() for g in gs[10:]);level1_total=l1_dictionary+l1_references+bridges+random_residual;l2_dictionary=3;level2_references=len(l2_occ);level2_total=l1_dictionary+l2_dictionary+level2_references+random_residual
 checks=[]
 for row,g in zip(l2_occ,gs[:10]):
  rec=reconstruct({'original_bindings':json.loads(row['original_bindings_json'])});checks.append(nx.is_isomorphic(rec,g,node_match=lambda a,b:a['kind']==b['kind'],edge_match=lambda a,b:a['relation']==b['relation']))
 deps=nx.DiGraph();deps.add_edges_from([('Pattern_L2_AB','Pattern_L1_A'),('Pattern_L2_AB','Pattern_L1_B')])
 integrated,integrated_vals=integrated_hierarchy();vals={'level2_depends_on_level1':set(deps.successors('Pattern_L2_AB'))=={'Pattern_L1_A','Pattern_L1_B'},'support_counts_exact':counts=={'patterns_by_level':{'1':2,'2':1},'l1_occurrences':20,'l2_occurrences':10,'original_graph_support':10},'all_original_occurrences_reconstruct':all(checks),'random_witnesses_not_supported':not ({'g10','g11'}&{r['graph_id'] for r in l2_occ}),'positive_level1_gain':level1_total<raw,'positive_recursive_gain':level2_total<level1_total,'dependency_graph_acyclic':nx.is_directed_acyclic_graph(deps),'every_l2_occurrence_links_two_l1_occurrences':all(len(json.loads(r['child_occurrence_ids_json']))==2 for r in l2_occ),**integrated_vals};assert all(vals.values()),(vals,raw,level1_total,level2_total)
 result={'patterns':patterns,'counts':counts,'hierarchy':nx.node_link_data(deps,edges='edges'),'level2_occurrences':l2_occ,'reconstruction_checks':dict(zip([g.graph['graph_id'] for g in gs[:10]],checks)),'random_witness_graphs':['g10','g11'],'description_length':{'unit':'one structural item or occurrence reference','raw_units':raw,'after_level1_units':level1_total,'after_level2_units':level2_total,'level1_gain':raw-level1_total,'recursive_additional_gain':level1_total-level2_total,'total_gain':raw-level2_total,'components':{'level1_dictionary':l1_dictionary,'level1_references':l1_references,'bridges_before_level2':bridges,'level2_dictionary':l2_dictionary,'level2_references':level2_references,'random_residual':random_residual}},'integrated_hierarchy':integrated,'validations':vals};(OUT/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');summary={'original_graphs':12,'level1_patterns':2,'level1_occurrences':20,'level2_patterns':1,'level2_occurrences':10,'raw_description_units':raw,'level2_description_units':level2_total,'total_gain_units':raw-level2_total,'integrated_level2_occurrences':len(integrated['level2_occurrences']),'integrated_recursive_gain':integrated['description_length']['recursive_additional_gain'],'integrated_promoted':integrated['decision']['promote'],'verdict':'GO_RECURSIVE_HIERARCHICAL_COMPRESSION'};(OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');(OUT/'versions-and-parameters.json').write_text(json.dumps({'generated_at':datetime.now(timezone.utc).isoformat(),'platform':platform.platform(),'networkx':importlib.metadata.version('networkx'),'duckdb':importlib.metadata.version('duckdb'),'pyarrow':importlib.metadata.version('pyarrow'),'description_model':'node/edge=1 unit, pattern occurrence reference=1 unit; dictionaries and unmatched residual structures counted','integrated_source_hashes':integrated['sources']},indent=2)+'\n');print(f'IND-06: L2 motif-of-motifs supports 10 graphs; description {raw}->{level2_total}; GO')
